package com.nemaz.school.common.persistence;

import java.util.UUID;

import jakarta.persistence.Id;
import jakarta.persistence.MappedSuperclass;
import org.hibernate.Hibernate;
import org.hibernate.annotations.UuidGenerator;

/**
 * Root of every entity with a surrogate UUIDv7 key (Database_Design §1): the id is
 * generated by Hibernate when the entity is persisted, so ids are time-ordered and
 * index-friendly. Entities without {@code created_at}/{@code version} columns extend this
 * directly; the usual base is {@link BaseEntity}. Reference tables keyed by ISO or standard
 * codes (countries, languages, ...) extend neither.
 *
 * <p>
 * Identity: two entities are equal when they are the same persistent class and share a
 * non-null id. A transient entity (no id yet) is equal only to itself, and
 * {@link #hashCode()} is constant per class so the hash does not change when the id is
 * assigned (safe in hash sets across persist).
 */
@MappedSuperclass
public abstract class IdentifiedEntity {

	@Id
	@UuidGenerator(style = UuidGenerator.Style.VERSION_7)
	private UUID id;

	public UUID getId() {
		return this.id;
	}

	@Override
	public final boolean equals(Object other) {
		if (this == other) {
			return true;
		}
		if (other == null || Hibernate.getClass(this) != Hibernate.getClass(other)) {
			return false;
		}
		UUID otherId = ((IdentifiedEntity) other).getId();
		return this.getId() != null && this.getId().equals(otherId);
	}

	@Override
	public final int hashCode() {
		return Hibernate.getClass(this).hashCode();
	}

}
